INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-001', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > A.L.O.U.D. > Step 1: Apologies', 1, 1, 'A - Apologies. Apologise sincerely before commenting further.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-002', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > A.L.O.U.D. > Step 2: Listen without interrupting', 2, 2, 'L - Listen without interrupting. Let the guest finish. Do not interrupt.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-003', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > A.L.O.U.D. > Step 3: Own the problem', 3, 3, 'O - Own the problem. Take ownership rather than deflecting to another department.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-004', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > A.L.O.U.D. > Step 4: Understand the difficulty', 4, 4, 'U - Understand the difficulty. Confirm you understand what the guest actually experienced.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-005', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > A.L.O.U.D. > Step 5: Deal with matter to the guest''s satisfaction', 5, 5, 'D - Deal with matter to the guest''s satisfaction. Agree and deliver a resolution.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-006', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 1', 6, 1, 'Listen attentively without interrupting; stop current task, make eye contact.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-007', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 2', 7, 2, 'Stay calm - the guest''s frustration is not about you personally.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-008', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 3', 8, 3, 'Apologise sincerely before commenting further, regardless of fault.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-009', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 4', 9, 4, 'Repeat the complaint back, acknowledging the guest''s feelings.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-010', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 5', 10, 5, 'Show empathy explicitly.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-011', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 6', 11, 6, 'Uncover what resolution the guest actually expects.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-012', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 7', 12, 7, 'Discuss and agree a solution together.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-013', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 8', 13, 8, 'Take action and follow through to confirm the guest is satisfied.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-014', 'prop-dublin-01', 'sop-foh-complaint', 'Complaint Handling > Step 9', 14, 9, 'If escalation is needed: ask the guest to take a seat, brief the manager with full details, and the manager on duty logs it in the complaint log.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-015', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 1', 15, 1, 'Welcome guest whilst making good eye contact with a genuine smile.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-016', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 2', 16, 2, 'Communicate with guest in order to establish a relationship.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-017', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 3', 17, 3, 'Never say ''No'' - offer an appropriate alternative.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-018', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 4', 18, 4, 'Be yourself whilst portraying a professional manner, friendly and willing to help.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-019', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 5', 19, 5, 'Anticipate and delight by understanding guest needs.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-020', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 6', 20, 6, 'Commitment to making it right.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-021', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 7', 21, 7, 'Empathy is key when dealing with issues.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-022', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 8', 22, 8, 'An engaged team radiates a positive environment.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-023', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 9', 23, 9, 'Respect guest privacy and confidentiality at all times.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-024', 'prop-dublin-01', 'sop-service-promise', 'Service Promise > Principle 10', 24, 10, 'A positive farewell is an opportunity for another hello.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-025', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Prohibited > 1', 25, NULL, 'Never chew gum while on duty.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-026', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Prohibited > 2', 26, NULL, 'Never refer to a guest by their room number.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-027', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Prohibited > 3', 27, NULL, 'Do not shout across guests to other employees.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-028', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Prohibited > 4', 28, NULL, 'Never argue with another employee in front of a guest.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-029', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Prohibited > 5', 29, NULL, 'No mobile phones while on duty.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-030', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Required > 1', 30, NULL, 'Greet guests as you see them - use their name when possible.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-031', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Required > 2', 31, NULL, 'Always smile.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-032', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Required > 3', 32, NULL, 'Remain standing when dealing with a guest at a desk.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-033', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Required > 4', 33, NULL, 'Maintain eye contact and an open posture; keep arms unfolded.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-034', 'prop-dublin-01', 'sop02-professional-ethic', 'Professional Ethic > Required > 5', 34, NULL, 'Give the guest your full attention.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-035', 'prop-dublin-01', 'sop-positive-alternatives', 'Positive Alternatives > 1', 35, NULL, 'Never say ''no problem''. Instead: certainly / absolutely / of course.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-036', 'prop-dublin-01', 'sop-positive-alternatives', 'Positive Alternatives > 2', 36, NULL, 'Never say ''no''. Instead: offer an appropriate alternative.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-037', 'prop-dublin-01', 'sop-positive-alternatives', 'Positive Alternatives > 3', 37, NULL, 'Never say ''I don''t know''. Instead: always give an alternative to the guest.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-038', 'prop-dublin-01', 'sop-positive-alternatives', 'Positive Alternatives > 4', 38, NULL, 'Never say ''I can''t tell you''. Instead: I regret that I do not have that information at hand, please let me get someone who may assist you.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-039', 'prop-dublin-01', 'sop-managing-your-station', 'Managing Your Station > Trigger 1', 39, 1, 'Glass one-third full or near empty - offer another round.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-040', 'prop-dublin-01', 'sop-managing-your-station', 'Managing Your Station > Trigger 2', 40, 2, 'Busy and cannot attend immediately - make eye contact and set an expectation.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-041', 'prop-dublin-01', 'sop-managing-your-station', 'Managing Your Station > Trigger 3', 41, 3, 'Check back within 2 minutes of food delivery.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-042', 'prop-dublin-01', 'sop-managing-your-station', 'Managing Your Station > Trigger 4', 42, 4, 'Observe your station and check each table for needs.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-043', 'prop-dublin-01', 'sop05-eleven-steps', '11 Steps of Service > 1. greet_on_approach', 43, 1, 'Greet the guest when 5 steps away, eye contact, appropriate phrase.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-044', 'prop-dublin-01', 'sop05-eleven-steps', '11 Steps of Service > 2. drinks_order', 44, 2, 'Drinks order taken within 3 minutes.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-045', 'prop-dublin-01', 'sop05-eleven-steps', '11 Steps of Service > 3. food_order', 45, 3, 'Food order taken within 2 minutes of readiness.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-046', 'prop-dublin-01', 'sop05-eleven-steps', '11 Steps of Service > 4. satisfaction_check', 46, 4, 'Customer satisfaction checked 2 minutes after food delivery.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-047', 'prop-dublin-01', 'sop05-eleven-steps', '11 Steps of Service > 5. payment', 47, 5, 'Payment collected within 2 minutes of guest readiness.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-048', 'prop-dublin-01', 'sop05-eleven-steps', '11 Steps of Service > 6. farewell', 48, 6, 'Thank guest for coming and invite him/her back.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-049', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > Authority and Approval > 1', 49, NULL, 'Staff may resolve a complaint themselves if they feel confident.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-050', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > Authority and Approval > 2', 50, NULL, 'Staff may offer a complimentary item (coffee or beverage) at their discretion.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-051', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > Authority and Approval > 3', 51, NULL, 'Refunds must be approved by the department manager/supervisor BEFORE being discussed with the guest.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-052', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > Authority and Approval > 4', 52, NULL, 'All complaints are reported to the department manager even when resolved.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-053', 'prop-dublin-01', 'sop-fnb-complaint', 'Complaint Handling > Authority and Approval > 5', 53, NULL, 'Comp items must be posted to a management account and signed for by the manager.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-054', 'prop-dublin-01', 'sop-escalation', 'Escalation > Rule 1', 54, NULL, 'Escalate to manager: seat the guest, brief the manager, manager logs in complaint log.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-055', 'prop-dublin-01', 'sop-escalation', 'Escalation > Rule 2', 55, NULL, 'All complaints logged with the General Manager/Duty Manager no matter how minor.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-056', 'prop-dublin-01', 'sop-escalation', 'Escalation > Rule 3', 56, NULL, 'Incident reports reviewed by H&S officer or GM within 72 hours; once signed off by the GM the report cannot be edited.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-057', 'prop-dublin-01', 'sop-escalation', 'Escalation > Rule 4', 57, NULL, 'Inform department manager about all guest complaints even when already resolved.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-058', 'prop-dublin-01', 'culture-deck', 'Culture > Statement 1', 58, NULL, 'All team members anticipate guest needs.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-059', 'prop-dublin-01', 'culture-deck', 'Culture > Statement 2', 59, NULL, 'All team members to deliver a positive experience for all customers.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-060', 'prop-dublin-01', 'culture-deck', 'Culture > Statement 3', 60, NULL, 'Instil a culture where guest expectations are anticipated and exceeded.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-061', 'prop-dublin-01', 'culture-deck', 'Culture > Statement 4', 61, NULL, 'Guests choose a hotel because they feel in good hands.');
INSERT INTO sop_chunk (id, property_id, document_id, section_path, ordinal, step_number, content) VALUES ('chunk-062', 'prop-dublin-01', 'culture-deck', 'Culture > Statement 5', 62, NULL, 'Create acts of kindness that are voluntary, unscripted and spontaneous.');
